import{z as s,x as l,o as A,c as i,q as t,j as e,D as a,d as r,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"期货深化案例与收束","description":"","frontmatter":{"title":"期货深化案例与收束","date":"2026-09-19T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ft-case-map.md","filePath":"quant/ft-case-map.md","lastUpdated":1791413859000}'),C={name:"quant/ft-case-map.md"};function p(d,E,D,f,h,_){const B=l("Mermaid");return A(),i("div",null,[E[2]||(E[2]=t('<h1 id="期货深化案例与收束" tabindex="-1">期货深化案例与收束 <a class="header-anchor" href="#期货深化案例与收束" aria-label="Permalink to &quot;期货深化案例与收束&quot;">​</a></h1><div class="epigraph"><p>展期的账只有两种记法：一种把到期当作远处的麻烦，一种把每一次换月当作一次小额交易决策的复利；深化的全部内容，就是把前者改写成后者。</p><footer>—— 据本课程各课的决策单与 Working, 1949；Cootner, 1960 整理</footer></div><p><a href="/quant/ft-seasonal-patterns">上一课</a>把库存写回展期：日历、成本、执行三件工具状态化，\\(\\partial y/\\partial I\\lt 0\\) 让晚滚变成持有负向选择权。本课是<a href="/quant/ft-roll-cost-modeling">期货与展期深化</a>课程的收束：用三个跨板块的案例把六课的决策单走一遍，再收拢成一张可审计的展期检查表。后课默认已经读完本课程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>商品、国债、股指三个板块的展期各有其物理：商品的仓储与仓单在交割地，国债的 CTD 在一篮子券里切换，股指的分红剩余在日历上漂移。缺口的共性是：把「展期」当成日历上的一次性动作，而不是一张需要状态化、可审计、可归因的决策表。三个案例分别演示决策单在哪一步裁决了不同的错误。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>决策单固定为五问：<strong>持哪张</strong>（近月还是远月，库存与季节说话）；<strong>换哪张</strong>（目标合约由成本与流动性定，不由习惯定）；<strong>哪天走</strong>（窗口由宽度与风险预算定，状态化阈值触发）；<strong>怎么拆</strong>（单腿风险与跨期腿的记账口径）；<strong>错了归谁</strong>（展期损益单独归因，不混进 alpha）。三个案例都按这五问逐项过，先商品、再国债、后股指。</p><p><span class="marginnote">术语翻译：「错了归谁」就是展期归因——每过一次换月，把「按公开答案滚会是多少、实际滚成多少」的差额单独记一本账。混进 alpha 的展期成本是隐形回撤，事后没人说得清亏在哪一课。</span></p>',8)),(A(),e(o,null,{default:a(()=>[n(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CASE%5B%22%E4%B8%89%E4%B8%AA%E6%A1%88%E4%BE%8B%EF%BC%9A%E5%95%86%E5%93%81%20%2F%20%E5%9B%BD%E5%80%BA%20%2F%20%E8%82%A1%E6%8C%87%22%5D%20--%3E%20Q1%5B%22%E6%8C%81%E5%93%AA%E5%BC%A0%EF%BC%9A%E5%BA%93%E5%AD%98%E4%B8%8E%E5%AD%A3%E8%8A%82%22%5D%0A%20%20CASE%20--%3E%20Q2%5B%22%E6%8D%A2%E5%93%AA%E5%BC%A0%EF%BC%9A%E6%88%90%E6%9C%AC%E4%B8%8E%E6%B5%81%E5%8A%A8%E6%80%A7%22%5D%0A%20%20CASE%20--%3E%20Q3%5B%22%E5%93%AA%E5%A4%A9%E8%B5%B0%EF%BC%9A%E7%8A%B6%E6%80%81%E5%8C%96%E7%AA%97%E5%8F%A3%22%5D%0A%20%20CASE%20--%3E%20Q4%5B%22%E6%80%8E%E4%B9%88%E6%8B%86%EF%BC%9A%E8%B7%A8%E6%9C%9F%E8%85%BF%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20CASE%20--%3E%20Q5%5B%22%E9%94%99%E4%BA%86%E5%BD%92%E8%B0%81%EF%BC%9A%E5%B1%95%E6%9C%9F%E5%BD%92%E5%9B%A0%22%5D%0A%20%20Q1%20--%3E%20T%5B%22%E5%8F%AF%E5%AE%A1%E8%AE%A1%E7%9A%84%E5%B1%95%E6%9C%9F%E6%A3%80%E6%9F%A5%E8%A1%A8%22%5D%0A%20%20Q2%20--%3E%20T%0A%20%20Q3%20--%3E%20T%0A%20%20Q4%20--%3E%20T%0A%20%20Q5%20--%3E%20T%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<p><span class="marginnote">Cootner 1960 把「展期收益」从幸存者的轶事变成可测量的理论对象；本课的检查表是同一件事的工程版。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><strong>案例一，商品</strong>：低库存年被动滚多头的代价在 <a href="/quant/ft-roll-inventory-revisit">展期与库存再探</a> 里已经算过——负向选择权。决策单的裁决在第三问：窗口不是日历日，而是库存分位触发，宽度过宽就持近月收条件收益，宁可多付一次移仓。<strong>案例二，国债</strong>：CTD 切换让「换哪张」的答案在行情里漂移，久期跳变必须按 <a href="/quant/ft-roll-cost-modeling">展期成本建模</a> 的账单口径单独限额，不能混进利率观点。<strong>案例三，股指</strong>：分红日历漂移使贴水读数季节化，指数滚法是公开答案（<a href="/quant/ft-index-roll-strategy">指数展期的策略执行</a>），偏离公开答案的每一分预期收益都要交出对应约束的证明。三案合看，<a href="/quant/ft-calendar-arb-deep">跨期套利深化</a> 的「带」是共同的计价对象，<a href="/quant/ft-seasonal-patterns">季节模式</a> 是共同的校准背景。</p>',3)),(A(),e(o,null,{default:a(()=>[n(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22%E5%95%86%E5%93%81%EF%BC%9A%E4%BD%8E%E5%BA%93%E5%AD%98%E5%B9%B4%22%5D%20--%3E%20P1%5B%22%E7%89%A9%E7%90%86%EF%BC%9A%E4%BB%93%E5%82%A8%E4%B8%8E%E4%BB%93%E5%8D%95%E5%9C%A8%E4%BA%A4%E5%89%B2%E5%9C%B0%22%5D%0A%20%20P1%20--%3E%20A1%5B%22%E7%AC%AC%E4%B8%89%E9%97%AE%E8%A3%81%E5%86%B3%EF%BC%9A%E7%AA%97%E5%8F%A3%E6%8C%89%E5%BA%93%E5%AD%98%E5%88%86%E4%BD%8D%E8%A7%A6%E5%8F%91%22%5D%0A%20%20C2%5B%22%E5%9B%BD%E5%80%BA%EF%BC%9ACTD%20%E5%9C%A8%E4%B8%80%E7%AF%AE%E5%AD%90%E5%88%B8%E9%87%8C%E5%88%87%E6%8D%A2%22%5D%20--%3E%20P2%5B%22%E7%89%A9%E7%90%86%EF%BC%9A%E5%90%88%E7%BA%A6%E4%B9%85%E6%9C%9F%E9%9A%8F%E5%88%87%E6%8D%A2%E8%B7%B3%E5%8F%98%22%5D%0A%20%20P2%20--%3E%20A2%5B%22%E7%AC%AC%E5%9B%9B%E9%97%AE%E8%A3%81%E5%86%B3%EF%BC%9A%E8%B7%B3%E5%8F%98%E5%8D%95%E7%8B%AC%E9%99%90%E9%A2%9D%22%5D%0A%20%20C3%5B%22%E8%82%A1%E6%8C%87%EF%BC%9A%E5%88%86%E7%BA%A2%E6%97%A5%E5%8E%86%E6%BC%82%E7%A7%BB%22%5D%20--%3E%20P3%5B%22%E7%89%A9%E7%90%86%EF%BC%9A%E8%B4%B4%E6%B0%B4%E8%AF%BB%E6%95%B0%E5%AD%A3%E8%8A%82%E5%8C%96%22%5D%0A%20%20P3%20--%3E%20A3%5B%22%E7%AC%AC%E4%BA%94%E9%97%AE%E8%A3%81%E5%86%B3%EF%BC%9A%E5%81%8F%E7%A6%BB%E5%85%AC%E5%BC%80%E6%BB%9A%E6%B3%95%E9%A1%BB%E8%AF%81%E6%98%8E%22%5D%0A%20%20A1%20--%3E%20Z%5B%22%E5%85%B1%E5%90%8C%E8%AE%A1%E4%BB%B7%E5%AF%B9%E8%B1%A1%EF%BC%9A%E8%B7%A8%E6%9C%9F%E5%B8%A6%22%5D%0A%20%20A2%20--%3E%20Z%0A%20%20A3%20--%3E%20Z%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p><span class="marginnote">数字实例：国债 CTD 从久期约 4 年的券切到约 7 年的券，多头期货的利率敏感度一夜之间接近翻倍；若不把这次跳变单独记账限额，原有的对冲比例就全错了——这正是第四问要拦住的事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>决策单覆盖的是「持仓的存续」；交割的物理流程、交割违约与仓单法律问题不在本课程，做实盘交割需要另读交易所交割规则。展期执行里的跨期腿在深度不足的市场会显著变宽，此时本单的第三问与第五问可能同时失效——那不是检查表的缺陷，是市场告诉你别滚。</p><p><span class="marginnote">常见误区：初学者把展期当成「到期前一天记得换个合约」的日历杂务。实际上展期是一串小交易决策的复利：滚早滚晚、目标合约选谁、怎么拆单，每一步都有成本、都能归因，攒起来能吃掉被动收益的一大块。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五问决策单：持哪张、换哪张、哪天走、怎么拆、错了归谁；三板块各有其物理，检查表同一张。</li><li>商品看库存分位，国债看 CTD 漂移，股指看分红日历；共同计价对象是跨期「带」。</li><li>展期损益单独归因，混进 alpha 的展期成本是隐形回撤。</li><li>出处：Working, <em>AER</em>, 1949；Cootner, 1960；本课程各课的决策单。</li></ul>',6))])}const u=s(C,[["render",p]]);export{F as __pageData,u as default};
